package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 1000000007

func modPow(a, e int64) int64 {
	res := int64(1)
	a %= MOD
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var x int64
	var n int64
	if _, err := fmt.Fscan(in, &x, &n); err != nil {
		return
	}

	// factorize x
	var primes []int64
	tmp := x
	for p := int64(2); p*p <= tmp; p++ {
		if tmp%p == 0 {
			primes = append(primes, p)
			for tmp%p == 0 {
				tmp /= p
			}
		}
	}
	if tmp > 1 {
		primes = append(primes, tmp)
	}

	ans := int64(1)
	for _, p := range primes {
		// compute exponent of p in product over y=1..n of g(y,p)
		// exponent = sum_{k>=1} floor(n / p^k)
		exp := int64(0)
		pp := p
		for pp <= n {
			exp += n / pp
			if pp > n/p {
				break
			}
			pp *= p
		}
		ans = ans * modPow(p%MOD, exp) % MOD
	}

	fmt.Println(ans)
}

